create table if not exists public.volunteer_roles (id uuid primary key default gen_random_uuid(), organization_id uuid not null, name text not null, role_type text not null, certification_required boolean not null default false, metadata jsonb not null default '{}'::jsonb, unique(organization_id,name));
create table if not exists public.volunteer_assignments (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.volunteer_opportunities(id) on delete cascade, volunteer_person_id uuid not null, role_id uuid references public.volunteer_roles(id), status text not null default 'assigned', checked_in_at timestamptz, completed_at timestamptz, credits_awarded numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(opportunity_id,volunteer_person_id,role_id));
create table if not exists public.volunteer_credentials (id uuid primary key default gen_random_uuid(), person_id uuid not null, credential_type text not null, credential_number text, governing_body_id uuid, issued_on date, expires_on date, status text not null default 'active', evidence_document_id uuid, unique(person_id,credential_type,credential_number));
create table if not exists public.document_acknowledgements (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, document_version_id uuid references public.document_versions(id) on delete set null, person_id uuid not null, acknowledgement_type text not null default 'read', acknowledged_at timestamptz not null default now(), source text not null default 'ls1', unique(document_id,person_id,acknowledgement_type));
create table if not exists public.governing_body_data_sources (id uuid primary key default gen_random_uuid(), governing_body_id uuid, sport_id uuid, source_type text not null, name text not null, base_url text, authority_level text not null default 'authoritative', status text not null default 'planned', last_synced_at timestamptz, metadata jsonb not null default '{}'::jsonb, unique(governing_body_id,sport_id,source_type,name));
create table if not exists public.athlete_rankings (id uuid primary key default gen_random_uuid(), athlete_id uuid not null references public.athletes(id) on delete cascade, sport_id uuid, event_code text, governing_body_id uuid, ranking_scope text not null, rank integer not null, points numeric, ranking_date date not null, source_system text not null, source_reference text, metadata jsonb not null default '{}'::jsonb, unique(athlete_id,event_code,ranking_scope,ranking_date,source_system));
create table if not exists public.integration_endpoints (id uuid primary key default gen_random_uuid(), tenant_id uuid, organization_id uuid, integration_type text not null, provider text not null, direction text not null check(direction in ('inbound','outbound','bidirectional')), status text not null default 'configured', configuration jsonb not null default '{}'::jsonb, last_success_at timestamptz, last_error_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.integration_sync_runs (id uuid primary key default gen_random_uuid(), endpoint_id uuid not null references public.integration_endpoints(id) on delete cascade, started_at timestamptz not null default now(), completed_at timestamptz, status text not null default 'running', records_received integer not null default 0, records_written integer not null default 0, records_rejected integer not null default 0, error_summary text, metadata jsonb not null default '{}'::jsonb);
create table if not exists public.competition_hardware_connections (id uuid primary key default gen_random_uuid(), competition_id uuid not null references public.competitions(id) on delete cascade, device_id uuid, provider text not null, connection_type text not null, lane_scope text, status text not null default 'configured', last_heartbeat_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(competition_id,provider,connection_type,device_id));
create table if not exists public.notification_preferences (id uuid primary key default gen_random_uuid(), person_id uuid not null, tenant_id uuid, channel text not null check(channel in ('in_app','email','sms','push')), event_type text not null default '*', enabled boolean not null default true, quiet_hours_start time, quiet_hours_end time, timezone text, updated_at timestamptz not null default now(), unique(person_id,tenant_id,channel,event_type));
create table if not exists public.platform_authority_grants (id uuid primary key default gen_random_uuid(), tenant_id uuid, subject_person_id uuid not null, resource_type text not null, resource_id uuid, action text not null, grantor_person_id uuid, authority_source text not null, valid_from timestamptz not null default now(), valid_until timestamptz, status text not null default 'active', metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists platform_authority_grants_lookup_idx on public.platform_authority_grants(subject_person_id,resource_type,resource_id,action,status);
